entries[165807] = { ["name"] = "Schutzwall des düsteren Gladiators", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+6 [Beweglichkeit oder Stärke oder Intelligenz]\nAnlegen: Wenn Eure Gesundheit unter 25% fällt, erhaltet Ihr einen Schild, der 6 Sek. lang [ 314 * (1 + Vielseitigkeit)] Schaden absorbiert. Dieser Effekt kann nur einmal alle 3 Min. auftreten.\nVerkaufspreis:" }
