entries[166260] = { ["name"] = "Pläne: Monelitgehärtete Hufplatten", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man monelitgehärtete Hufplatten effektiver herstellt.\nVerringert erheblich die erforderlichen Materialien zur Herstellung von monelitgehärteten Hufplatten.\nBenötigt Schmiedekunst von Kul Tiras (95)\nVerkaufspreis:\nMonelitgehärtete Hufplatten\nBenutzen: Beschlägt Euer Reittier mit Hufplatten, die Eure Geschwindigkeit beim Reiten in Kul Tiras oder Zandalar für 2 Stunden um 20% erhöhen.\n\nDie Dauer ist für Schmiede vervierfacht.\nBenötigt Moneliterz (15), Langlebiger Fluxus (2)" }
entries[166263] = { ["name"] = "Rezept: Blutiges Festmahl", ["text"] = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man ein blutiges Festmahl effektiver herstellt.\nVerbraucht weniger Zutaten bei der Zubereitung von blutigen Festmahlen.\nBenötigt Kochkunst von Kul Tiras (1)\nBenötigt Tortollanische Sucher\n- Ehrfürchtig\nVerkaufspreis:\nBlutiges Festmahl\nBenutzen: Richtet ein blutiges Festmahl her, das bis zu 35 Mitglieder Eures Schlachtzugs oder Eurer Gruppe sättigen kann!\n\nStellt im Verlauf von 20 Sek. 38462 Gesundheit und 23077 Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und ein Wert wird 1 Stunde lang um 46 erhöht.\nVerkaufspreis:\nBenötigt Zähe Lende (18), Fleischige Keule (18), Frische Kartoffel (28), Aromatisches Fischöl (17), Blutzelle (17)" }
entries[166264] = { ["name"] = "Rezept: Blutiges Festmahl", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man ein blutiges Festmahl effektiver herstellt.\nVerbraucht deutlich weniger Zutaten bei der Zubereitung von blutigen Festmahlen.\nBenötigt Kochkunst von Kul Tiras (1)\nVerkaufspreis:\nBlutiges Festmahl\nBenutzen: Richtet ein blutiges Festmahl her, das bis zu 35 Mitglieder Eures Schlachtzugs oder Eurer Gruppe sättigen kann!\n\nStellt im Verlauf von 20 Sek. 38462 Gesundheit und 23077 Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und ein Wert wird 1 Stunde lang um 46 erhöht.\nVerkaufspreis:\nBenötigt Zähe Lende (15), Fleischige Keule (15), Frische Kartoffel (25), Aromatisches Fischöl (15), Blutzelle (15)" }
