entries[166276] = { ["name"] = "Bauplan: Instabiler temporaler Zeitverschieber", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man einen instabilen temporalen Zeitverschieber effizienter herstellt.\nVerringert erheblich die erforderlichen Materialien zur Herstellung eines instabilen temporalen Zeitverschiebers.\nBenötigt Ingenieurskunst von Kul Tiras (1)\nVerkaufspreis:\nInstabiler temporaler Zeitverschieber\nBenutzen: Kehrt um ein kürzlich verstorbenes Ziel den Fluss der Zeit um und lässt es mit 60% Gesundheit sowie 20% Mana ins Leben zurückkehren. Kann im Kampf eingesetzt werden.\n\nEs besteht eine Chance auf eine Fehlzündung, die den Fluss der Zeit um ein Ziel beschleunigt und somit zu einem Verlust von Vitalität führt.\n\nKann nicht von Spielercharakteren über Stufe 50 eingesetzt werden. (10 Min Abklingzeit)\nBenötigt Ingenieurskunst von Kul Tiras (85)\n\"Dieses Gerät kann zwar die Toten ins Leben zurückrufen, versetzt aber unter Umständen auch die Lebenden an die Schwelle des Todes.\"\nBenötigt Moneliterz (8), Sturmsilbererz (6), Isoliertes Kabel (15)" }
entries[166277] = { ["name"] = "Bauplan: Instabiler temporaler Zeitverschieber", ["text"] = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man einen instabilen temporalen Zeitverschieber effizienter herstellt.\nVerringert die erforderlichen Materialien zur Herstellung eines instabilen temporalen Zeitverschiebers.\nBenötigt Ingenieurskunst von Kul Tiras (1)\nBenötigt Prachtmeeradmiralität\n- Ehrfürchtig\nVerkaufspreis:\nInstabiler temporaler Zeitverschieber\nBenutzen: Kehrt um ein kürzlich verstorbenes Ziel den Fluss der Zeit um und lässt es mit 60% Gesundheit sowie 20% Mana ins Leben zurückkehren. Kann im Kampf eingesetzt werden.\n\nEs besteht eine Chance auf eine Fehlzündung, die den Fluss der Zeit um ein Ziel beschleunigt und somit zu einem Verlust von Vitalität führt.\n\nKann nicht von Spielercharakteren über Stufe 50 eingesetzt werden. (10 Min Abklingzeit)\nBenötigt Ingenieurskunst von Kul Tiras (85)\n\"Dieses Gerät kann zwar die Toten ins Leben zurückrufen, versetzt aber unter Umständen auch die Lebenden an die Schwelle des Todes.\"\nBenötigt Moneliterz (10), Sturmsilbererz (7), Isoliertes Kabel (18)" }
entries[166278] = { ["name"] = "Technik: Vertrag: 7. Legion", ["text"] = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man einen Vertrag: 7. Legion effizienter herstellt.\nVerringert die erforderlichen Materialien zur Herstellung eines Vertrages: 7. Legion.\nBenötigt Inschriftenkunde von Kul Tiras (1)\nBenötigt7. Legion\n- Wohlwollend\nVerkaufspreis:\nAllianz\nVertrag: 7. Legion\nBenutzen: Schließt einen Vertrag mit der 7. Legion ab, der Euch jedes Mal Ruf bei dieser Fraktion gewährt, wenn Ihr Weltquests in Kul Tiras oder Zandalar abschließt.\nBenötigt7. Legion\n- Freundlich\nVerkaufspreis:\nHorde\nVertrag: Die Eidgebundenen\nBenutzen: Schließt einen Vertrag mit den Eidgebundenen ab, der Euch jedes Mal Ruf bei dieser Fraktion gewährt, wenn Ihr Weltquests in Kul Tiras oder Zandalar abschließt.\nBenötigt Die Eidgebundenen\n- Freundlich\nVerkaufspreis:\nBenötigt Leichtes Pergament , Ultramarinblaue Tinte (15), Blutrote Tinte (8)" }
