entries[166367] = { ["name"] = "Rezept: Wildbeerenbrot", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man Wildbeerenbrot effektiver herstellt.\nIhr verschwendet nichts von Euren Zutaten und stellt so bei jeder Zubereitung viel mehr Wildbeerenbrot her.\nBenötigt Kochkunst von Kul Tiras (1)\nBenötigt Tortollanische Sucher\n- Ehrfürchtig\nVerkaufspreis:\nWildbeerenbrot\nBenutzen: Stellt im Verlauf von 20 Sek. 19231 Gesundheit und 11538 Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang 52 Ausdauer.\nVerkaufspreis:\nBenötigt Wildes Mehl (8), Wilde Beeren (8), Puderzucker (5), Aromatisches Fischöl (2)" }
entries[166368] = { ["name"] = "Rezept: Würziges Steak mit Kartoffeln", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man würziges Steak mit Kartoffeln effektiver herstellt.\nIhr verschwendet nichts von Euren Zutaten und stellt so bei jeder Zubereitung viel mehr würzige Steaks mit Kartoffeln her.\nBenötigt Kochkunst von Kul Tiras (1)\nBenötigt Tortollanische Sucher\n- Ehrfürchtig\nVerkaufspreis:\nWürziges Steak mit Kartoffeln\nBenutzen: Stellt im Verlauf von 20 Sek. 38462 Gesundheit und 23077 Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang 69 Ausdauer.\nVerkaufspreis:\nBenötigt Dickes Paleosteak (6), Frische Kartoffel (5), Fusaka (2), Aromatisches Fischöl (2)" }
