entries[166422] = { ["name"] = "Rezept: Silas' Sphäre der Transmutation", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man Silas' Sphäre der Transmutation herstellt.\nStellt Silas' Sphäre der Transmutation her.\nBenötigt Alchemie von Kul Tiras\n(150)\nVerkaufspreis:\nSilas' Sphäre der Transmutation\nWird beim Aufheben gebunden\nEinzigartig\nHebt verschiedene Kessel in Kul Tiras und Zandalar hervor und gestattet es dem Spielercharakter, mit ihnen zu interagieren.\nBenutzen: Konzentriert Euch auf die Sphäre, um sie für 1 Stunde in ein anderes Objekt zu verwandeln.\nBenötigt Alchemie von Kul Tiras\n(150)\n\"Die Oberfläche der Sphäre verändert sich ständig und zeigt verschiedene Bilder für jeweils einen Augenblick, aber nie lang genug, um sie genau zu erkennen.\"\nBenötigt Penetrant potenter Trank , Sphäre aus Sangaurum , Extrem präzise Phiole , Karaffe des verschlagenen Schurken , Ankerkraut (50), Mystischer Kessel , Expulsom (10)" }
entries[166428] = { ["name"] = "Schwarzpranke", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Schwarzpranke oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Schwarzpranke war eigentlich im Winterschlaf und wollte seine Ruhe haben, und plötzlich war da eine Kriegsfront.\"\nBeute von:\nAgathe Wyrmholz\nZone:\nDunkelküste\n\nBeute von:\nZone:\nDunkelküste" }
entries[166432] = { ["name"] = "Schimäre des Eschentals", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört eine Schimäre des Eschentals oder gibt sie wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Die Kaldorei verwenden häufig die Schimären des Eschentals, um in Schlachten die Gebäude der Menschen, Orcs und Untoten zu vernichten.\"\nBeute von:\nAlash'anir\nZone:\nDunkelküste" }
entries[166433] = { ["name"] = "Verängstigter Kodo", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen reitbaren verängstigten Kodo oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Nichts verstört einen Kodo mehr als ein Bär mit Geweih.\"\nBeute von:\nZone:\nDunkelküste" }
entries[166434] = { ["name"] = "Gefangener umbrabrauner Nachtsäbler", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen reitbaren umbrabraunen Nachtsäbler oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Nachtsäbler sind ein wesentlicher Bestandteil der Armee der Kaldorei und dienen gleichermaßen als Reittiere und Angriffswaffen.\"\nBeute von:\nMoxo der Köpfer\nZone:\nDunkelküste\n\nBeute von:\nAthil Tauglanz\nZone:\nDunkelküste" }
entries[166435] = { ["name"] = "Nachtsäbler der Kaldorei", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen reitbaren Nachtsäbler der Kaldorei oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Die Verbindung zwischen Nachtsäbler und seinem Jäger oder seiner Jägerin ist kaum zu brechen.\"\nBeute von:\nCroz Blutzorn\nZone:\nDunkelküste\n\nBeute von:\nSchattenklaue\nZone:\nDunkelküste" }
entries[166436] = { ["name"] = "Goldbrauner Nachtsäbler", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man einen goldbraunen Nachtsäbler beschwört.\nBeschwört einen reitbaren goldbrauner Nachtsäbler oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nSchließt die Schlacht um die Dunkelküste auf dem Schwierigkeitsgrad 'Heroisch' ab.\n\n\"Nachtsäbler dieser Farbe sind sehr selten und kaum zu finden. Bei Jägerinnen erfreuen sie sich großer Beliebtheit.\"\nVerkäufer:\nVersorgerin Starkschmied\nZone:\nTiragardesund\nKosten:\n350\n\nVerkäufer:\nVersorgerin Mukra\nZone:\nZuldazar\nKosten:\n350" }
