entries[166442] = { ["name"] = "Blauer Sumpfhüpfer", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen blauen Sumpfhüpfer oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Dieses schmatzende Geräusch bei jedem Schritt? Das ist eine Spezialfertigkeit und kein Makel.\"\nVerkäufer:\nHabse\nZone:\nNazmir\nKosten:" }
