entries[166467] = { ["name"] = "Inseldonnerschuppe", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Eine der größten einheimischen Drachenarten von Azeroth. Diese Unterart ernährt sich fast ausschließlich von Fischen. Und Fischern.\"\nBeute von:\nInselexpeditionen" }
entries[166468] = { ["name"] = "Blutgesättigter Jäger", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Wenn er nicht so voll wäre, hättet Ihr ihn nicht erwischt.\"\nBeute von:\nInselexpeditionen" }
entries[166469] = { ["name"] = "Blutrünstige Unheilschwinge", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenötigt eine Horde-Rasse\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Die Verlassenen benutzen bevorzugt diese blutrünstigen Jäger, denn sie sind nicht nur rasante Reittiere, sondern haben auch einen verstörenden Effekt auf die Psyche ihrer Gegner.\"\nVerkäufer:\nVersorgerin Mukra\nZone:\nZuldazar\nKosten:\n750" }
entries[166470] = { ["name"] = "Steinhauturhorn", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Euer Steinhauturhorn oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Die Steinhauturhörner sind eine von wenigen Elcharten, die das Inselklima vertragen, da ihr Fell dünner ausfällt als bei den meisten Urhörnern.\"\nBeute von:\nInselexpeditionen" }
entries[166471] = { ["name"] = "Salzwasserseepferdchen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört ein reitbares Salzwasserseepferdchen oder gibt es wieder frei. Dieses Reittier ist ein geschickter Schwimmer.\n\nAufgrund seiner kapriziösen Natur kann seine Schwimmgeschwindigkeit durch Effekte, die die Reitgeschwindigkeit erhöhen oder verringern, nicht beeinflusst werden.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Diese riesigen Seepferde sind von Natur aus neugierig und durchsuchen oft versunkene Schiffswracks nach Glitzerkram.\"\nVerkäufer:\nKapitänin Klarisa\nZone:\nTiragardesund\nKosten:\n500\n\nVerkäufer:\nKapitänin Zen'taga\nZone:\nZuldazar\nKosten:\n500" }
