entries[166539] = { ["name"] = "Windschnitter von Dazar'alor", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Euren Windschnitter von Dazar'alor oder gibt ihn wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Diese wilden Tiere gleiten hoch über der Schlacht von Dazar'alor und lassen sich nur von den gerissensten Siegern anlocken.\"\nErfolg:\nRuhm des Schlachtzüglers von Dazar'alor\nKategorie:\nDungeons & Schlachtzüge" }
entries[166540] = { ["name"] = "Vorlage: Machtgetränkter Krakenaugenring", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man einen machtgetränkten Krakenaugenring herstellt.\nStellt einen machtgetränkten Krakenaugenring her.\nBenötigt Juwelierskunst von Kul Tiras\n(130)\nVerkaufspreis:\nMachtgetränkter Krakenaugenring\nWird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+5 Ausdauer\n\nPrismatischer Sockel\n\nBenötigt Juwelierskunst von Kul Tiras\n(130)\nVerkaufspreis:\nBenötigt Krakenauge (3), Laribol (30), Scharlachdiamant (30), Expulsom (20), Blutzelle (25)" }
