entries[166662] = { ["name"] = "Knatschige Krabbe", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Beschwört eine äußerst knatschige Krabbe, auf der Euer Kampfhaustier reiten kann. (10 Min Abklingzeit)\n\"Sie ist mit der Gesamtsituation unzufrieden.\"\nVerkaufspreis:" }
entries[166663] = { ["name"] = "Handanker", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Benutzt den Anker als Waffe. (1 Stunde Abklingzeit)\n\"Der kann im Notfall ganz schön wehtun.\"\nVerkaufspreis:" }
entries[166664] = { ["name"] = "Glyphe 'Sturmwacht'", ["text"] = "Klassen: Magier\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Wasserelementar wird durch die hellblaue Variante ersetzt, die die Gezeitenpriester bevorzugen. Exklusiv mit: Glyphe 'Unbändiger Elementar' Glyphe 'Verdampfen' Glyphe 'Gezeiten' Glyphe 'Finstere Tiefe' Glyphe 'Dampfende Wut' Glyphe 'Kältewellen'\nVerkaufspreis:" }
entries[166665] = { ["name"] = "Technik: Glyphe 'Sturmwacht'", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man die Glyphe 'Sturmwacht' schreibt.\nBenötigt Inschriftenkunde von Kul Tiras (150)\nVerkaufspreis:\nGlyphe 'Sturmwacht'\nKlassen: Magier\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Wasserelementar wird durch die hellblaue Variante ersetzt, die die Gezeitenpriester bevorzugen. Exklusiv mit: Glyphe 'Unbändiger Elementar' Glyphe 'Verdampfen' Glyphe 'Gezeiten' Glyphe 'Finstere Tiefe' Glyphe 'Dampfende Wut' Glyphe 'Kältewellen'\nVerkaufspreis:\nBenötigt Leichtes Pergament , Blutrote Tinte (10), Ultramarinblaue Tinte (30)" }
