entries[166724] = { ["name"] = "Bruce", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Bruce oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"BRUCE!\"\nQuest:\nSchließt die Questreihe der Kampfgilde ab" }
