entries[166729] = { ["name"] = "Spaltbeil des gefürchteten Aspiranten", ["text"] = "Wird beim Aufheben gebunden\nEinhändig Axt\n5 - 12 Schaden Geschwindigkeit 2.60\n(3.3 Schaden pro Sekunde)\n+3 Beweglichkeit\n+5 Ausdauer\nErhöht Eure Tempowertung um + 4.\nErhöht Eure Meisterschaftswertung um + 2.\nHaltbarkeit 90 / 90Benötigt eine Allianz-Rasse\nVerkaufspreis:" }
