entries[166732] = { ["name"] = "Stoßsichere Brustverstärkung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Kombiniert ein stahlbeschlagenes Primatenexoskelett, eine stoßsichere Brustverstärkung und eine bananenförmige Energiezelle, um einen mächtigen Gorillakampfroboter zusammenzubauen." }
