entries[166734] = { ["name"] = "Bananenförmige Energiezelle", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Kombiniert ein stahlbeschlagenes Primatenexoskelett, eine stoßsichere Brustverstärkung und eine bananenförmige Energiezelle, um einen mächtigen Gorillakampfroboter zusammenzubauen." }
entries[166735] = { ["name"] = "Mechaspinndrüse", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Kombiniert eine Handvoll Glasspinnenaugen, ein stahlbeschlagenes Arachnidenexoskelett und eine Mechaspinndrüse, um einen mächtigen Spinnenkampfroboter zusammenzubauen." }
entries[166736] = { ["name"] = "Bauplan: Instabiler temporaler Zeitverschieber", ["text"] = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man einen instabilen temporalen Zeitverschieber effizienter herstellt.\nVerringert die erforderlichen Materialien zur Herstellung eines instabilen temporalen Zeitverschiebers.\nBenötigt Ingenieurskunst von Kul Tiras (1)\nBenötigt Zandalariimperium\n- Ehrfürchtig\nVerkaufspreis:\nInstabiler temporaler Zeitverschieber\nBenutzen: Kehrt um ein kürzlich verstorbenes Ziel den Fluss der Zeit um und lässt es mit 60% Gesundheit sowie 20% Mana ins Leben zurückkehren. Kann im Kampf eingesetzt werden.\n\nEs besteht eine Chance auf eine Fehlzündung, die den Fluss der Zeit um ein Ziel beschleunigt und somit zu einem Verlust von Vitalität führt.\n\nKann nicht von Spielercharakteren über Stufe 50 eingesetzt werden. (10 Min Abklingzeit)\nBenötigt Ingenieurskunst von Kul Tiras (85)\n\"Dieses Gerät kann zwar die Toten ins Leben zurückrufen, versetzt aber unter Umständen auch die Lebenden an die Schwelle des Todes.\"\nBenötigt Moneliterz (10), Sturmsilbererz (7), Isoliertes Kabel (18)" }
entries[166737] = { ["name"] = "Handvoll Glasspinnenaugen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Kombiniert eine Handvoll Glasspinnenaugen, ein stahlbeschlagenes Arachnidenexoskelett und eine Mechaspinndrüse, um einen mächtigen Spinnenkampfroboter zusammenzubauen." }
entries[166738] = { ["name"] = "Stahlbeschlagenes Arachnidenexoskelett", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Kombiniert eine Handvoll Glasspinnenaugen, ein stahlbeschlagenes Arachnidenexoskelett und eine Mechaspinndrüse, um einen mächtigen Spinnenkampfroboter zusammenzubauen." }
