entries[166742] = { ["name"] = "Preisgekröntes pandarisches Chili", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Richtet für Eure Gruppe oder Euren Schlachtzug ein Festmahl aus Steak und Kartoffeln her!\n\nStellt im Verlauf von 20 Sek. 5% Gesundheit und 5% Mana wieder her. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang 10% Ausdauer.\n\nKann nur auf Schlachtfeldern verwendet werden.\nVerkaufspreis:" }
entries[166743] = { ["name"] = "Seuchenbomber", ["text"] = "Wird bei Benutzung gebunden\nSpielzeug\nBenutzen: Beschwört und kontrolliert Euren Seuchenbomber. (30 Sek. Abklingzeit)\n\"Verseucht alles!\"\nVerkaufspreis:" }
entries[166744] = { ["name"] = "Glevenwerfer", ["text"] = "Wird bei Benutzung gebunden\nSpielzeug\nBenutzen: Beschwört und kontrolliert Euren Glevenwerfer. (30 Sek. Abklingzeit)\n\"Verteidigt die Wildnis!\"\nVerkaufspreis:" }
entries[166745] = { ["name"] = "Schlickflügelalbatros", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Dieser Albatros gehört zu den seltensten Vögeln der Inseln des Großen Meeres. Er ist bei Händlern begehrt – wenn es ihnen denn gelingt, ihn einzufangen.\"\nVerkäufer:\nKapitänin Klarisa\nZone:\nTiragardesund\nKosten:\n1000\n\nVerkäufer:\nKapitänin Zen'taga\nZone:\nZuldazar\nKosten:\n1000" }
entries[166746] = { ["name"] = "Ruhestein des Feuerschluckers", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Bringt Euch zurück nach: Ruhestein-Ort. Sprecht mit einem Gastwirt an einem anderen Ort, um Euren Heimatort zu ändern.\n\"Kehrt auf die heißeste Art und Weise nach Hause zurück!\"" }
entries[166747] = { ["name"] = "Ruhestein des Braufestfeiernden", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Bringt Euch zurück nach: Ruhestein-Ort. Sprecht mit einem Gastwirt an einem anderen Ort, um Euren Heimatort zu ändern.\n\"Kehrt auf die ausgelassenste Art und Weise nach Hause zurück!\"" }
entries[166749] = { ["name"] = "Liedtext: Lied des Meeres", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verbessert Eure Pfeife des Flugmeisters, sodass Ihr auf einer Inselexpedition einen Flug zurück zu Eurem Schiff anfordern könnt.\nVerkaufspreis:" }
entries[166750] = { ["name"] = "Destillat der zehn Länder", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Erhöht alle Werte für 1 Stunde um 5 und die erhaltene Erfahrung um 10%. (3 Sek. Abklingzeit)\n\"Eine seltene Mischung aus vielen Ingredienzien, die von Verbündeten aus ganz Azeroth stammen.\"" }
