entries[166752] = { ["name"] = "Klingenbesetzter Umhang des Steingardisten", ["text"] = "Erbstück Aufwertungsstufe: 0/0\nWird an Kriegsmeute gebunden\nRücken\n6 Rüstung\n+6 [Beweglichkeit oder Stärke oder Intelligenz]\n+9 Ausdauer\nErhöht Eure Tempowertung um + 6.\n+ 6 Vielseitigkeit\nBenötigt eine Horde-Rasse\n29 ( 29)\n\"Ein Umhang, der an frisch eingezogene Rekruten ausgehändigt wird.\"\n\nOrnat der sagenhaften Abenteurer (0/7)\nErbstückbrustrüstung\nErbstückhelm\nErbstückschultern\nErbstückumhang\nErbstückbeinrüstung\nErbstückkette\nErbstückring\n(2) Set : Verringert den Verbrauch des Ruhebonus um 30%.\n(3) Set : Erhöht in Außengebieten, in normalen Dungeons und auf Schlachtfeldern Eure Regeneration außerhalb des Kampfes.\n(5) Set : Ein Stufenaufstieg löst eine 'Explosion des Wissens' aus, die Gegnern in der Nähe 1126 Heiligschaden zufügt und Eure Hauptwert 2 Min. lang um 40% erhöht. Das Besiegen von Gegnern verlängert diesen Effekt um bis zu zusätzlich 2 Min.\n(6) Set : Verringert den Verbrauch des Ruhebonus um zusätzlich 30%.\n\nVerkäufer:\nVersorgerin Mukra\nZone:\nZuldazar" }
entries[166753] = { ["name"] = "Orcisches Kriegshorn", ["text"] = "Erbstück Aufwertungsstufe: 0/0\nWird an Kriegsmeute gebunden\nEinzigartig anlegbar\nSchmuck\n+14 Ausdauer\nBenötigt eine Horde-Rasse\nBenutzen: Erhöht die Vielseitigkeit aller Gruppenmitglieder innerhalb von 40 Metern 20 Sek. lang um 13 . (2 Min Abklingzeit)\n29 ( 29)\n\"Ein Gegenstand, der an frisch eingezogene Rekruten ausgehändigt wird.\"\n\nVerkäufer:\nVersorgerin Mukra\nZone:\nZuldazar" }
