entries[166769] = { ["name"] = "Zwergisches Kriegshorn", ["text"] = "Erbstück Aufwertungsstufe: 0/0\nWird an Kriegsmeute gebunden\nEinzigartig anlegbar\nSchmuck\n+14 Ausdauer\nBenötigt eine Allianz-Rasse\nBenutzen: Erhöht die Vielseitigkeit aller Gruppenmitglieder innerhalb von 40 Metern 20 Sek. lang um 13 . (2 Min Abklingzeit)\n29 ( 29)\n\"Ein Gegenstand, der an frisch eingezogene Rekruten ausgehändigt wird.\"\n\nVerkäufer:\nVersorgerin Starkschmied\nZone:\nBoralus" }
entries[166770] = { ["name"] = "Gesäumter gilnearischer Umhang", ["text"] = "Erbstück Aufwertungsstufe: 0/0\nWird an Kriegsmeute gebunden\nRücken\n6 Rüstung\n+6 [Beweglichkeit oder Stärke oder Intelligenz]\n+9 Ausdauer\nErhöht Eure Tempowertung um + 6.\n+ 6 Vielseitigkeit\nBenötigt eine Allianz-Rasse\n29 ( 29)\n\"Ein Umhang, der an frisch eingezogene Rekruten ausgehändigt wird.\"\n\nOrnat der sagenhaften Abenteurer (0/7)\nErbstückbrustrüstung\nErbstückhelm\nErbstückschultern\nErbstückumhang\nErbstückbeinrüstung\nErbstückkette\nErbstückring\n(2) Set : Verringert den Verbrauch des Ruhebonus um 30%.\n(3) Set : Erhöht in Außengebieten, in normalen Dungeons und auf Schlachtfeldern Eure Regeneration außerhalb des Kampfes.\n(5) Set : Ein Stufenaufstieg löst eine 'Explosion des Wissens' aus, die Gegnern in der Nähe 1126 Heiligschaden zufügt und Eure Hauptwert 2 Min. lang um 40% erhöht. Das Besiegen von Gegnern verlängert diesen Effekt um bis zu zusätzlich 2 Min.\n(6) Set : Verringert den Verbrauch des Ruhebonus um zusätzlich 30%.\n\nVerkäufer:\nVersorgerin Starkschmied\nZone:\nBoralus" }
entries[166771] = { ["name"] = "Behelfsmäßige Handkanone", ["text"] = "Questgegenstand\nBenutzen: Feuert eine Rakete auf einen eingefrorenen Hordezeppelin ab, um ihn in die Luft zu jagen. Fügt Gegnern am Zielort Feuerschaden zu. (10 Sek. Abklingzeit)" }
entries[166773] = { ["name"] = "Goblinsprengstoff", ["text"] = "Die Dunkelküste\nQuestgegenstand\nEinzigartig\n\"Welcher Wahnsinnige hat sich gedacht, es wäre eine gute Idee, Sprengstoff einfach herumliegen zu lassen?\"" }
entries[166774] = { ["name"] = "Hogrus, das Schwein des Glücks", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Hogrus wurde zum ersten Mal von Kaiser Shaohao nach dreitägiger Meditation erblickt. Er gilt bei den Pandaren als Symbol dafür, dass das Glück zu dem kommt, der handelt.\"\nWoW-Shop" }
entries[166775] = { ["name"] = "Fuchsfamiliar", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Diese fuchsartigen Wesen stammen aus den Großen Dunklen Weiten und haben von dort ihren Weg nach Azeroth gefunden. Auf der Suche nach Abenteuern und Gesellschaft schließen sie sich bevorzugt Azeroths Champions an. Zwei Eigenschaften zeichnen sie vor allem aus: ihre überdurchschnittliche Intelligenz und ihre Neugierde.\"\nWoW-Shop" }
entries[166776] = { ["name"] = "Sylverischer Träumer", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Eine Künstlerin in der magischen Stadt von Dalaran übermannte bei ihrer Arbeit der Schlaf und im Traum malte sie das Bild eines wunderschönen gefiederten Drachen. Ihr Bild wurde lebendig und als sie erwachte, fand sie den Drachen vor sich, der friedlich an ihrer Seite schlummerte.\"\nWoW-Shop" }
entries[166777] = { ["name"] = "Feuerwerk \"Löwenstolz\"", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Lasst an der Leiche eines frisch gefallenen Spielercharakters der Horde ein Feuerwerk hochgehen. (3 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[166778] = { ["name"] = "Feuerwerk \"Macht der Horde\"", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Lasst der Leiche eines frisch gefallenen Spielercharakters der Allianz ein Feuerwerk hochgehen. (3 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[166779] = { ["name"] = "Transmorphersignal", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Beschwört einen astralen Transmorpher, der Euch für 20 Min. eine andere Gestalt verleihen kann. (1 Stunde Abklingzeit)" }
entries[166782] = { ["name"] = "Perle des Abgrunds", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Ihr habt das überwältigende Gefühl, die dunkle Perle auf Eurem Kopf platzieren zu müssen... Warum solltet Ihr so etwas tun?! (2 Std. Abklingzeit)" }
entries[166784] = { ["name"] = "Narassins Seelenedelstein", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Fängt die Seele des Ziels in Narassins Seelenedelstein. Funktioniert nur bei toten Zielen. (1 Min Abklingzeit)" }
entries[166785] = { ["name"] = "Entgiftete Seuchengranate", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Wirft eine entgiftete Seuchengranate auf das Ziel und bedeckt es mit entgifteter Seuche. (10 Min Abklingzeit)" }
entries[166787] = { ["name"] = "Handkreisel: Schildwachengleve", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\n\"Sieht nicht ganz ungefährlich aus...\"" }
entries[166788] = { ["name"] = "Handkreisel: Schredderklinge", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\n\"Passt auf Eure Finger auf!\"" }
entries[166790] = { ["name"] = "Hochgeborenenandenken", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Lasst zu, dass Ihr von einem Hochgeborenengeist besessen werdet. (1 Stunde Abklingzeit)" }
entries[166791] = { ["name"] = "Makellose Falkenfeder", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick Euren Falken von Korlach beschwören oder wieder freigeben.\n80 ( 80)" }
entries[166792] = { ["name"] = "Vorgeschmack des Sieges", ["text"] = "Wird beim Aufheben gebunden\nDie in Kul Tiras und Zandalar erhaltene Erfahrung ist um 10% erhöht. Funktioniert nur bis Stufe 49." }
entries[166793] = { ["name"] = "Uralter Knorren der Weisheit", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure Meisterschaftswertung um + 9.\nBenutzen: Erhöht Eure Intelligenz um ( 1 * 20). Dieser Wert verringert sich alle 4 Sek. um ( 1 * 4). (1 Min Abklingzeit)\nVerkaufspreis:" }
entries[166794] = { ["name"] = "Klingenblatt des Waldlords", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+6 Beweglichkeit\nAnlegen: Eure Angriffe haben eine Chance, Eure kritischen Trefferwert für 16 Sek. um 24 zu erhöhen.\nVerkaufspreis:" }
entries[166795] = { ["name"] = "Knoten der urzeitlichen Wut", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+6 Stärke\nBenutzen: Erhöht Euren kritischen Trefferwert 12 Sek. lang um 36 . (1 Min Abklingzeit)\nVerkaufspreis:" }
