entries[166797] = { ["name"] = "Sterntopas", ["text"] = "Wird beim Aufheben gebunden\nDauer: 20 std. (Realzeit)\nBenutzen: Bringt einen verbündeten Spielercharakter zum Funkeln! (30 Sek. Abklingzeit)" }
