entries[166799] = { ["name"] = "Smaragd der Erquickung", ["text"] = "Wird beim Aufheben gebunden\nDauer: 20 std. (Realzeit)\nBenutzen: Stellt 8000 Gesundheit wieder her. (1 Min Abklingzeit)" }
entries[166800] = { ["name"] = "Diamant der Stärkung", ["text"] = "Wird beim Aufheben gebunden\nDauer: 20 std. (Realzeit)\nBenutzen: Erhaltet Stärkung von dem Stein und stellt im Verlauf von 20 Sek. 38462 Gesundheit und 19231 Mana wieder her. Wenn Ihr Euch mindestens 10 Sek. auf den Stein konzentriert, werdet Ihr satt und ein Wert wird 1 Stunde lang um 46 erhöht." }
entries[166801] = { ["name"] = "Saphir der Brillanz", ["text"] = "Wird beim Aufheben gebunden\nDauer: 20 std. (Realzeit)\nBenutzen: Erhöht alle Werte 1 Min. lang um 120 . (5 Min Abklingzeit)" }
entries[166802] = { ["name"] = "Zauberklinge des Pestbringers", ["text"] = "Wird beim Aufheben gebunden\nEinhändig Schwert\n3 - 6 Schaden Geschwindigkeit 2.60\n(1.7 Schaden pro Sekunde)\n+18 Intelligenz\n+5 Ausdauer\n+ 4 Vielseitigkeit\nErhöht Eure Meisterschaftswertung um + 2.\nHaltbarkeit 110 / 110Benötigt eine Horde-Rasse\nVerkaufspreis:" }
entries[166803] = { ["name"] = "Umbrabrauner Nachtsäbler", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen reitbaren umbrabraunen Nachtsäbler oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Nachtsäbler sind ein wesentlicher Bestandteil der Armee der Kaldorei und dienen gleichermaßen als Reittiere und Angriffswaffen.\"\nBeute von:\nMoxo der Köpfer\nZone:\nDunkelküste\n\nBeute von:\nAthil Tauglanz\nZone:\nDunkelküste" }
entries[166804] = { ["name"] = "Blutwurst aus Boralus", ["text"] = "Benutzen: Stellt im Verlauf von 20 Sek. 38462 Gesundheit und 23077 Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und ein Wert wird 1 Stunde lang um 39 erhöht.\nVerkaufspreis:" }
entries[166805] = { ["name"] = "Blutverschmierte Einladung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verschafft allen Charakteren Eurer Kriegsmeute Zugang zur Kampfgilde.\nVerkaufspreis:" }
entries[166806] = { ["name"] = "Rezept: Blutwurst aus Boralus", ["text"] = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man Blutwurst aus Boralus effektiver herstellt.\nStellt bei jeder Zubereitung zusätzliche Blutwurst aus Bolarus her.\nBenötigt Kochkunst von Kul Tiras (1)\nBenötigt Tortollanische Sucher\n- Ehrfürchtig\nVerkaufspreis:\nBlutwurst aus Boralus\nBenutzen: Stellt im Verlauf von 20 Sek. 38462 Gesundheit und 23077 Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und ein Wert wird 1 Stunde lang um 39 erhöht.\nVerkaufspreis:\nBenötigt Dickes Paleosteak (5), Fusaka (3), Aromatisches Fischöl (2), Blutzelle (5)" }
entries[166807] = { ["name"] = "Rezept: Blutwurst aus Boralus", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man Blutwurst aus Boralus effektiver herstellt.\nIhr verschwendet nichts von Euren Zutaten und stellt so bei jeder Zubereitung viel mehr Blutwurst aus Bolarus her.\nBenötigt Kochkunst von Kul Tiras (1)\nVerkaufspreis:\nBlutwurst aus Boralus\nBenutzen: Stellt im Verlauf von 20 Sek. 38462 Gesundheit und 23077 Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und ein Wert wird 1 Stunde lang um 39 erhöht.\nVerkaufspreis:\nBenötigt Dickes Paleosteak (5), Fusaka (3), Aromatisches Fischöl (2), Blutzelle (5)" }
entries[166808] = { ["name"] = "Verzauberndes Teeservice", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Organisiert eine verzaubernde Teeparty für Eure Freunde. (15 Min Abklingzeit)" }
entries[166809] = { ["name"] = "Herausforderungskarte: Tock Tausendhammer", ["text"] = "Rang 8\nWird beim Aufheben gebunden\nEinzigartig: Herausforderungskarte (1)\n\"Einem Vertreter der Kampfgilde überreichen, um Tock Tausendhammer herauszufordern. Ihr könnt nur jeweils eine Herausforderungskarte besitzen.\"\nVerkaufspreis:" }
