entries[166881] = { ["name"] = "Gryzix' Werkzeugkasten", ["text"] = "Questgegenstand\n\"Der Werkzeugkasten von Datenguru Gryzix. Enthält einen Bogenlichtschraubenschlüssel, einen Eimer, einen Klemm-o-matik und zahlreiche gefälschte Goldmünzen.\"" }
entries[166882] = { ["name"] = "Goblinischer \"Gedankenverstärker\"", ["text"] = "Questgegenstand\n\"Angeblich macht es den Anwender sehr viel geschickter in Ingenieursdingen. Elektrios hat aber Gefallen daran gefunden, weil es sich so schön dreht.\"" }
entries[166883] = { ["name"] = "Mysteriöse Schatzkarte", ["text"] = "\"Ein Papier fragwürdiger Herkunft, das Euren Anhängern den Weg zu Ruhm und Reichtum weist.\"" }
entries[166884] = { ["name"] = "Kaum magischer Stab", ["text"] = "Wird beim Anlegen gebunden\nZweihändig Stab\n1 - 3 Schaden Geschwindigkeit 2.60\n(0.8 Schaden pro Sekunde)\n\"Dieser Stab versprüht magische Funken. Ihr habt schon beeindruckendere Stäbe gesehen... aber auch noch schlimmere.\"\nVerkaufspreis:" }
entries[166885] = { ["name"] = "Marke von Azshara", ["text"] = "Wird an Kriegsmeute gebunden\n\"Eine wunderschöne Münze, die einen Funken von Azsharas Herrlichkeit einfängt.\"" }
