entries[166890] = { ["name"] = "Verräterkönig", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Der SCHRECKLICHE König von Sturmwind hat uns alle hintergangen!\"\n<Zum Lesen rechtsklicken>\nVerkaufspreis:" }
