entries[166999] = { ["name"] = "Schatzkarte", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Gewährt eine lukrative Schatzkartenmission." }
entries[167001] = { ["name"] = "Zerknüllte Gleichungen", ["text"] = "\"Bei näherem Hinsehen wird klar, dass, wer auch immer dies geschrieben hat, nichts von Mathematik versteht.\"\nVerkaufspreis:" }
entries[167002] = { ["name"] = "Bauplan: Unterjustierte Corgibrille", ["text"] = "\"Ein fehlkonzipiertes Gerät, das dazu dienen sollte, Freunde niedlich aussehen zu lassen. Tatsächlich macht die Brille dem Träger lediglich bewusst, dass es Corgis wirklich gibt.\"\nVerkaufspreis:" }
entries[167003] = { ["name"] = "Bauplan: Echteisenofenhandschuhe", ["text"] = "\"Instruktionen zur Herstellung von Echteisenofenhandschuhen. Ein Zusatz am Ende der Anleitung besagt: '... umständlich in der Handhabung, sehr schwer, steif und schützen nur bedingt vor hohen Temperaturen.'\"\nVerkaufspreis:" }
entries[167004] = { ["name"] = "Bauplan: Ultrazeitverstärker Mk. 2", ["text"] = "\"Unvollständige Notizen zur Herstellung eines Ultrazeitverstärkers Mk. 2. Unter dem Punkt 'Funktion' steht Folgendes: 'Ermöglicht dem Träger, durch die Zeit zu reisen. Für jede Zeitreisesekunde wird eine Sekunde in der Ausgangszeitlinie zurückgelegt.'\"\nVerkaufspreis:" }
