entries[167167] = { ["name"] = "Ankoanischer Wellenrochen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Ankoaner der Meeresklinge\n- Ehrfürchtig\n\n\"Die Ankoaner kämpfen schon seit Jahren gegen die Naga. Durch ihre Verbundenheit mit dem Meer wurde das Zähmen der dort lebenden Tiere ganz natürlich Teil ihrer Strategie.\"\nVerkäufer:\nHandwerker Okata\nZone:\nNazjatar\nFraktion:\nAnkoaner - Ehrfürchtig\nKosten:\n250" }
