entries[167170] = { ["name"] = "Entfesselter Wellenrochen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Die Entfesselten\n- Ehrfürchtig\n\n\"Die Entfesselten fühlen sich mit den Wesen aus den Tiefen der Meere, die durch die Naga gelitten haben, auf natürliche Weise verbunden.\"\nVerkäufer:\nFinder Pruc\nZone:\nNazjatar\nFraktion:\nDie Entfesselten - Ehrfürchtig\nKosten:\n250" }
