entries[167217] = { ["name"] = "Beinplatten der entfesselten Qualen", ["text"] = "Wird beim Aufheben gebunden\nBeine Platte\n18 Rüstung\n+6 [Stärke oder Intelligenz]\n+9 Ausdauer\nErhöht Eure Tempowertung um + 6.\nHaltbarkeit 120 / 120\nAnlegen: Wenn Euer Ziel eine geringere prozentuale Gesundheit hat als Ihr, haben Eure Schadensfähigkeiten eine hohe Chance, 17 Eurer Gesundheit zu opfern, um [ 34 * (1 + Vielseitigkeit)] Schattenschaden zu verursachen. (500ms Abklingzeit)\nVerkaufspreis:" }
entries[167218] = { ["name"] = "Zaxasjs Tiefenschreiter", ["text"] = "Wird beim Aufheben gebunden\nFüße Stoff\n3 Rüstung\n+5 Intelligenz\n+7 Ausdauer\nErhöht Eure kritische Trefferwertung um + 3.\nErhöht Eure Meisterschaftswertung um + 6.\nHaltbarkeit 80 / 80\nAnlegen: Eure Geschwindigkeit ist pro 20% Eurer fehlenden Gesundheit um 200 erhöht (maximal 600).\nVerkaufspreis:" }
entries[167219] = { ["name"] = "Handschuhe des unsterblichen Paktes", ["text"] = "Wird beim Aufheben gebunden\nHände Leder\n5 Rüstung\n+5 [Beweglichkeit oder Intelligenz]\n+7 Ausdauer\nErhöht Eure Tempowertung um + 4.\n+ 1 Vielseitigkeit\nHaltbarkeit 55 / 55\nBenutzen: Bindet Euch an bis zu 5 Verbündete innerhalb von 20 Metern. Nach 6 Sek. werdet Ihr um 25% der Gesundheit geheilt, die bei verbundenen Verbündeten wiederhergestellt wurde (heilt maximal 495 Gesundheit). (1 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:" }
